new = '''interface SmokeRibbon {\n  mesh: THREE.Mesh<THREE.BufferGeometry, THREE.ShaderMaterial>;\n  points: Float32Array;\n  positions: Float32Array;\n  count: number;\n  width: number;\n  playerMissile: boolean;\n  retireSeconds: number;\n  retiredAge: number | null;\n}\n'''
