new = '        const color = enemyMissile ? 0xff8a2b : projectile.owner === "player-missile" ? 0xfff4de : 0xc8f8ff;\n        const geometry = projectile.owner === "player-missile"\n          ? new THREE.ConeGeometry(0.2, 1.26, 8)'
